"""Build the local listening/visual review for the shared face library."""
from pathlib import Path
import html
import json

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/generated/face-library-review'
LABELS=['Neutral','Calm','Anxiety','Fear','Panic','Sadness','Crying','Anger','Frustration','Disgust','Happiness','Relief','Surprise','Shame','Guilt','Confusion','Skepticism','Hope','Despondency','Numbness']
PROMPTS=['Attentive listening; relaxed mouth and natural blinking.','Settled face without a broad smile.','Uneasy anticipation and searching glances.','Present fear, widened eyes and slight recoil.','Escalating fear and overwhelm.','Sorrow, softer downturned mouth and lowered gaze.','Containing tears, then losing composure.','Directed anger: knitted brows and tense lips.','Impatience or feeling unheard; restrained tension.','Nose wrinkle, upper-lip lift and withdrawal.','A developing smile and softened eyes.','Tension visibly releases.','A brief unexpected reaction, then settling.','Self-conscious withdrawal and lowered gaze.','Troubled regret; tentative contact then looking away.','Searching expression and slight head tilt.','Doubt and guarded evaluation.','Tentative brightening and renewed attention.','Discouraged, low-energy responses.','Reduced expression with natural blinking.']
LIMITATIONS={1:'The raw transfer makes the resting brows look stern. Neutral calibration may help; this does not by itself call for a retake.',7:'This face-only preview adds no tears or body sobbing. Hands covering the face can obscure tracking; keep that section for body reference.',9:'Check sections where a hand approaches the face. The preview cannot reproduce the hand gesture.',14:'Eye direction is not transferred in this preview. Judge the source and facial/head motion separately.',15:'Eye direction is not transferred. Guilt and shame also need conversational context to distinguish them.',19:'Body posture is fixed, so low-energy posture is not represented.',20:'Stillness is intentional here; detection coverage alone cannot judge its emotional usefulness.'}
h=html.escape
LIMITATIONS.update({
    6:'Initial frame review: brow and mouth nuance is weaker on the character than in the recording. Assess the transfer before deciding on a retake.',
    7:'Initial frame review: crying transfers as a smile/grin in several sections. This needs tracking/mapping work. The preview also adds no tears or body sobbing.',
    8:'Initial frame review: the strong mouth opening can read as a grin because brow tension is weaker on the character. Check the transfer before asking for a different performance.',
    10:'A hand covers the nose in part of this take. Evaluate the unobstructed sections separately; the character has no corresponding hand animation.',
    11:'Initial frame review: the smile transfers clearly. Check the rounded-mouth sections for exaggerated mouth/tongue movement.',
    14:'Tracking is lost in some large head turns/downward poses. Eye direction is not transferred either. Usable sections may remain; review before deciding whether a smaller-turn retake is needed.',
    16:'Check the rounded-mouth sections for exaggerated mouth/tongue movement in the character.',
})

def main():
    rows=json.loads((OUT/'results.json').read_text())
    assert len(rows)==20,'Wait for all comparisons to finish'
    body='''<header><p class="eyebrow">PSYCHOLOGY VR · SHARED PERFORMANCE LIBRARY</p><h1>Facial recording review</h1><p>20 takes, one reusable library for all four characters. <strong>Left: your recording. Right: the actual Unity character.</strong> Play at normal speed; pause and scrub to compare the same moment.</p><p>These Android exports contain video, not recorded facial curves. Motion is estimated locally with MediaPipe, then mapped to the character. Full takes are shown without trimming, neutral correction or expression amplification. The number-to-emotion labels follow the supplied recording order; please flag any mismatch.</p><p class="notice">Preview limitations: fixed body and eye direction; no tears, hand gestures or face redness. Mouth motion comes from the recording, not generated speech. These clips have not replaced the live consultation animations.</p><button id="download">Download feedback</button> <span id="status" role="status">Choices save in this browser.</span><nav>'''
    for r in rows:body+=f'<a href="#take-{r["index"]}">{r["index"]:02d} {h(LABELS[r["index"]-1])}</a>'
    body+='</nav></header><main>'
    for r in rows:
        i=r['index'];folder=r['folder'];assert (OUT/folder/'comparison.mp4').is_file()
        body+=f'<section id="take-{i}" data-take="{i}"><h2>{i:02d} · {h(LABELS[i-1])}</h2><p>{h(PROMPTS[i-1])}</p>'
        body+=f'<p class="meta">MySlate_{i} · {r["duration"]:.1f} seconds · {r["tracking_percent"]}% face detection · video estimate</p>'
        if i in LIMITATIONS:body+=f'<p class="notice">{h(LIMITATIONS[i])}</p>'
        body+=f'<video controls preload="none" playsinline src="{folder}/comparison.mp4"></video><div class="labels"><span>Original performance</span><span>Unity transfer · unchanged mapping</span></div>'
        body+=f'<label>Assessment <select data-key="{i}" aria-label="Assessment for {h(LABELS[i-1])}"><option value="">Not reviewed</option><option>Good enough — keep</option><option>Recording good; fix character transfer</option><option>Keep part; trim or soften</option><option>Performance needs a retake</option><option>Wrong expression label</option></select></label>'
        body+=f'<textarea data-note="{i}" aria-label="Notes for {h(LABELS[i-1])}" placeholder="What works or needs changing? Include a time, e.g. 8.5 seconds."></textarea><button class="timestamp">Add current video time to notes</button> <a href="{folder}/contact.jpg">Frame comparison sheet</a></section>'
    body+='</main><footer><p>Detection percentage measures whether a face was found, not tracking accuracy or emotional quality. Original files are preserved. <a href="results.json">Technical report</a></p></footer>'
    css='''body{margin:0 auto;max-width:1120px;padding:32px 24px;font:17px/1.55 system-ui;color:#e5edf3;background:#101820}h1{font-size:38px}h2{margin-top:0}.eyebrow,.meta{font-size:14px;color:#a6bdcc}.notice{border-left:3px solid #d6af6e;padding:8px 15px;background:#252a2b}nav{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}a{color:#94d5ec}nav a{background:#243440;padding:5px 10px;border-radius:6px;text-decoration:none}section{scroll-margin-top:15px;background:#1b2933;border:1px solid #344751;border-radius:12px;padding:22px;margin:28px 0}video{display:block;width:100%;background:#0b1015}.labels{display:grid;grid-template-columns:1fr 1fr;text-align:center;color:#a6bdcc;margin:8px 0 20px}label{display:block}select,button,textarea{font:inherit;border:1px solid #718999;border-radius:6px;padding:9px}button{background:#b1dfd0;cursor:pointer;color:#132925}textarea{display:block;box-sizing:border-box;width:100%;min-height:84px;margin:12px 0;background:#101b24;color:#e5edf3}footer{padding:20px 0}@media(max-width:650px){body{padding:18px 10px}section{padding:12px}h1{font-size:29px}select{max-width:100%}}'''
    js='''const key="shared-face-library-review-v1";let data={};try{data=JSON.parse(localStorage.getItem(key)||"{}")}catch{};const save=()=>{localStorage.setItem(key,JSON.stringify(data));document.querySelector("#status").textContent="Saved locally"};document.querySelectorAll("section[data-take]").forEach(section=>{const id=section.dataset.take,select=section.querySelector("select"),notes=section.querySelector("textarea");select.value=data[id]?.choice||"";notes.value=data[id]?.notes||"";const update=()=>{data[id]={choice:select.value,notes:notes.value};save()};select.addEventListener("change",update);notes.addEventListener("input",update);section.querySelector(".timestamp").onclick=()=>{notes.value+=(notes.value?"\\n":"")+section.querySelector("video").currentTime.toFixed(1)+" s: ";notes.focus();update()}});document.querySelectorAll("video").forEach(v=>v.addEventListener("play",()=>document.querySelectorAll("video").forEach(other=>{if(other!==v)other.pause()})));document.querySelector("#download").onclick=()=>{const blob=new Blob([JSON.stringify({review:"shared-face-library-v1",saved_at:new Date().toISOString(),reviews:data},null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="shared-face-library-feedback.json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};'''
    (OUT/'review.js').write_text(js,encoding='utf-8')
    (OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shared facial performance review</title><style>'+css+'</style><body>'+body+'<script src="review.js"></script></body></html>',encoding='utf-8')
    print('Built complete 20-take review')

if __name__=='__main__':main()
